member.summary:
            Extended Test Execution Site
            0 to 255 (add 1 for actual test execution site)


            若需使用需使用以下程式碼覆寫


            
            get
            {
                return this.CurrentBytes.Array[this.CurrentBytes.Offset];
            }
            set
            {
                this.CurrentBytes.Array[this.CurrentBytes.Offset] = (byte)value;
            }

            Extended Binary Category
            0 to 127 (add 1 for actual test execution site)


            若需使用需使用以下程式碼覆寫


            
            get
            {
                return this.CurrentBytes.Array[this.CurrentBytes.Offset + 1];
            }
            set
            {
                this.CurrentBytes.Array[this.CurrentBytes.Offset + 1] = (byte)value;
            }

            Wafer Test Start Time 

若需使用需使用以下程式碼覆寫

get

{

    return DateTime.ParseExact(this.CurrentBytes.Array.SubByte(this.CurrentBytes.Offset + 20, 2).ByteArrayToASCIIString()

                             + this.CurrentBytes.Array.SubByte(this.CurrentBytes.Offset + 22, 2).ByteArrayToASCIIString()

                             + this.CurrentBytes.Array.SubByte(this.CurrentBytes.Offset + 24, 2).ByteArrayToASCIIString()

                             + this.CurrentBytes.Array.SubByte(this.CurrentBytes.Offset + 26, 2).ByteArrayToASCIIString()

                             + this.CurrentBytes.Array.SubByte(this.CurrentBytes.Offset + 28, 2).ByteArrayToASCIIString(),

                               "yyMMddHHmm", null);

}

set

{

    string temp = value.ToString("yyMMddHHmm");

    for (int i = 0; i < temp.Length; i++)

    {

        this.CurrentBytes.Array[this.CurrentBytes.Offset + 20 + i] = (byte)temp[i];

    }

}

