             實例化  物件，並以  讀取
              檔案的內容。

繼承後必須實作以下程式碼才可正確解析
             
             int currentIndex = 0;
             this.Header = new Header(new ArraySegment<byte>(this.TskBytes, 0, 236));
             currentIndex += this.Header.TSKHeaderByties.Count;
            
             this.ReadTskDie(ref currentIndex);
            
             char[] fileStruct = this.Header.FileStructure;
            
             #region Line Category Information
             if (fileStruct[2].Equals('1'))
             {
                 this.LineCategory = new ArraySegment<byte>(this.TskBytes, currentIndex, 2 * this.Header.MapDataAreaRowSize * this.Header.MapDataAreaLineSize);
                 currentIndex += this.LineCategory.Count;
             }
             #endregion
            
             #region Extended Header Information
             if (fileStruct[3].Equals('1'))
             {
                 this.ExtendedHeader = new ExtendedHeader(new ArraySegment<byte>(this.TskBytes, currentIndex, 172));
                 currentIndex += this.ExtendedHeader.CurrentBytes.Count;
             }
             #endregion
             
             #region Test Result Information Per Extended Die
             if (fileStruct[4].Equals('1'))
             {
                 this.ReadExtendedDie(ref currentIndex);
             }
             #endregion
             
             #region Extended Line Category Information
             if (fileStruct[5].Equals('1'))
             {
                 this.ExtendedLineCategory = new ArraySegment<byte>(this.TskBytes, currentIndex, 2 * this.Header.MapDataAreaRowSize * this.Header.MapDataAreaLineSize);
                 currentIndex += this.ExtendedLineCategory.Count;
             }
             #endregion
             
             #region Other Data
             if (currentIndex != this.TskBytes.Length)
             {
                 int length = this.TskBytes.Length - currentIndex;
                 this.OtherData = new ArraySegment<byte>(this.TskBytes, currentIndex, length);
             }
             #endregion

            讀取  檔的  資訊

繼承後必須實作以下程式碼才可正確解析

this.Dies = new List<AbstractDie>();

for (int i = 0; i < Header.MapDataAreaLineSize * this.Header.MapDataAreaRowSize; i++)

{

    Die d = new Die(new ArraySegment<byte>(this.TskBytes, currentIndex, 6));

    if (d.IsPassDie && !this.PassBins.Contains(d.DieCharacter))

    {

        this.PassBins.Add(d.DieCharacter);

    }

    this.Dies.Add(d);

    currentIndex += 6;

}

            解析 

繼承後必須實作以下程式碼才可正確解析

for (int i = 0; i < this.Dies.Count; i++)

{

    this.Dies[i].ExtendedDieData = new ExtendedDie(new ArraySegment<byte>(this.TskBytes, currentIndex, 4));

    currentIndex += 4;

}
